import path from "node:path";

/** The most characters of the name of a change or of a capability. */
export const NAME_CHARS_MAX = 60;

/**
 * A name is words of letters and digits in any script, joined by single hyphens: `add-export`, `dodaj-eksport`, or `エクスポート-追加`.
 * A letter is lower case or has no case, so the name is safe on a file system that ignores case.
 */
export const NAME_PATTERN =
  /^[\p{Ll}\p{Lo}\p{Lm}\p{M}\p{N}]+(?:-[\p{Ll}\p{Lo}\p{Lm}\p{M}\p{N}]+)*$/u;

/** The largest edit distance at which a bad command gets a suggestion of the nearest command. */
export const SUGGEST_DISTANCE_MAX = 2;

/** The most lines of a file that `minispec show` prints for a human. A longer file is cut, and the last line names the path. */
export const SHOW_LINES_MAX = 200;

/** The name of the folder of the finished changes, inside `minispec/changes/`. */
